/bin/bash -lc "cat > app/lib/posts.ts <<'EOF'
import { cacheTag } from 'next/cache';

export type Post = {
  id: string;
  title: string;
  content: string;
  createdAt: string;
};

let postsStore: Post[] = [
  {
    id: 'seed-1',
    title: 'Welcome post',
    content: 'This is a cached posts list.',
    createdAt: new Date().toISOString()
  }
];

export async function getPosts(): Promise<Post[]> {
  'use cache';

  cacheTag('posts');

  return postsStore.map((post) => ({ ...post }));
}

export async function createPost(input: {
  title: string;
  content: string;
}): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title: input.title,
    content: input.content,
    createdAt: new Date().toISOString()
  };

  postsStore = [post, ...postsStore];

  return post;
}
EOF"

